-- =================================================================================================
-- ACCESS RIGHTS (written by hand)
-- The app connects as edu_app: it may read and write rows, but not change tables.
-- =================================================================================================
GRANT USAGE ON SCHEMA public TO edu_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO edu_app;
-- Tables created by later migrations get the same rights automatically.
ALTER DEFAULT PRIVILEGES FOR ROLE edu_owner IN SCHEMA public
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO edu_app;

-- =================================================================================================
-- ROW SECURITY (written by hand): the database's safety net that keeps organizations apart.
--
-- The app already filters every query by organization. These policies make PostgreSQL enforce it
-- too, so a forgotten filter returns nothing instead of another organization's data.
--
-- The app tells PostgreSQL who is asking, per transaction (see src/prisma/prisma.service.ts):
--   app.organization_id = '<id>'   a user of that organization: only its rows are visible
--   app.bypass_rls      = 'on'     super admin and login lookups: every row is visible
-- Neither set: no rows at all.
--
-- A NEW TABLE WITH organization_id NEEDS THE SAME THREE LINES in its migration.
-- =================================================================================================

-- The organizations table: a row IS an organization, so it compares "id".
ALTER TABLE "organizations" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "organizations" FORCE ROW LEVEL SECURITY;
CREATE POLICY organization_isolation ON "organizations"
  USING (current_setting('app.bypass_rls', true) = 'on'
         OR "id"::text = current_setting('app.organization_id', true))
  WITH CHECK (current_setting('app.bypass_rls', true) = 'on'
         OR "id"::text = current_setting('app.organization_id', true));

-- Every table that belongs to an organization: same rule on "organization_id".
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['organization_modules', 'institutions', 'campuses', 'roles', 'users', 'audit_logs'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY organization_isolation ON %I
         USING (current_setting(''app.bypass_rls'', true) = ''on''
                OR "organization_id"::text = current_setting(''app.organization_id'', true))
         WITH CHECK (current_setting(''app.bypass_rls'', true) = ''on''
                OR "organization_id"::text = current_setting(''app.organization_id'', true))', t);
  END LOOP;
END
$$;
